func (a *AdapterV2) GetEndpointKey(endpoint *servicev1.ServiceEndpoint) string {
	zone := GetZone(endpoint)
	endpointKey := fmt.Sprintf("%s/%s/%s/%s/%s", EndpointPrefix, endpoint.Service.GetValue(), endpoint.Id.GetValue(), zone, url.QueryEscape(fmt.Sprintf("%s_%d", endpoint.Address.GetValue(), endpoint.Port.GetValue())))

	return endpointKey
}

// GetEndpointsPodUIDs scans the endpoint prefix on the PRIMARY etcd once and
// returns endpointKey -> pod_uid (utils.PodUIDMetaKey from the endpoint
// payload's Meta map); entries carrying no pod_uid are skipped. Used by Clean()
// Branch B as a belt-and-suspenders UID guard — one batched prefix Get per pass
// replaces a synchronous per-key Get for every alive-pod key. Reads primary
// only: the UID is pod identity and is identical across entity etcds, so one
// read suffices.
func (a *AdapterV2) GetEndpointsPodUIDs() (map[string]string, error) {
	if a.Client == nil {
		return nil, errors.New("etcd client in nil")
	}
	ctx, cancel := context.WithTimeout(a.ctx, 30*time.Second)
	defer cancel()
	res, err := a.Client.KV.Get(ctx, EndpointPrefix+"/", clientv3.WithPrefix(), clientv3.WithLimit(0))
	if err != nil {
		metrics.EtcdFailure.WithLabelValues("getEndpointsPodUIDs:Get", "").Inc()
		a.handleError(err)
		return nil, err
	}
	metrics.EtcdSuccess.WithLabelValues("getEndpointsPodUIDs:Get", "").Inc()

	uids := make(map[string]string, len(res.Kvs))
	for _, kv := range res.Kvs {
		var endpoint servicev1.ServiceEndpoint
		if err := endpoint.UnmarshalVT(kv.Value); err != nil {
			continue
		}
		if uid := endpoint.Meta[utils.PodUIDMetaKey]; uid != "" {
			uids[string(kv.Key)] = uid
		}
	}
	return uids, nil
}

func (a *AdapterV2) Register(endpoint *servicev1.ServiceEndpoint, isLRC bool) error {
	if a.Client == nil {
		return errors.New("etcd client in nil")
	}
	clustername := utils.GetClusterName()
	endpoint.HealthStatus = servicev1.HealthCheckStatus_HEALTHY
	zone := GetZone(endpoint)
	endpointKey := fmt.Sprintf("%s/%s/%s/%s/%s", EndpointPrefix, endpoint.Service.GetValue(), endpoint.Id.GetValue(), zone, url.QueryEscape(fmt.Sprintf("%s_%d", endpoint.Address.GetValue(), endpoint.Port.GetValue())))
	// V4 migration: LRC endpoints write catalog to v4 path. Remove post-migration.
	// Non-LRC v3.1 catalog writes are blocked unless BLOCK_V31_CATALOG_WRITES=false.
	catalogKey, writeCatalog := registerCatalogKey(endpoint.Service.GetValue(), endpoint.Port.GetValue(), isLRC, blockV31CatalogWrites.Load())
	parts := strings.Split(endpoint.Id.GetValue(), "/")
	nodeName, podName := parts[0], parts[1]
	nodeKey := fmt.Sprintf("%s/%s/%s/%s", NodePrefix, nodeName, endpoint.Service.GetValue(), podName)
	clusterKey := fmt.Sprintf("%s/%s/%s", ClusterPrefix, clustername, nodeName)

	serviceName, err := utils.KeyToServiceName(endpointKey)
	if err != nil {
		metrics.EtcdFailure.WithLabelValues("register:KeyToServiceName", serviceName).Inc()
		log.Error().Dict("custom_attributes", logger.Attrs().
			Str("status_code", string(logger.GALACTUS_ETCD_SERVICE_NAME_FAILED)).
			Str("operation", "register").
			Str("endpoint_key", endpointKey).
			Str("error", err.Error())).
			Msg(logger.Msg(logger.GALACTUS_ETCD_SERVICE_NAME_FAILED))
		return err
	}

	if !validator.ValidateKeyPath(endpointKey) {
		metrics.EtcdFailure.WithLabelValues("register:ValidateKeyPath", serviceName).Inc()
		log.Warn().Msgf("Register: validation failed for endpointKey=%s", endpointKey)
		return errors.New("register: validation failed for endpointKey")
	}

	isValid, err := validator.ValidateServiceEndpoint(endpoint)
	if err != nil {
		metrics.EtcdFailure.WithLabelValues("register:ValidateServiceEndpoint", serviceName).Inc()
		log.Error().Dict("custom_attributes", logger.Attrs().Str("status_code", string(logger.GALACTUS_ETCD_VALIDATION_FAILED)).Str("error", err.Error())).Msg(logger.Msg(logger.GALACTUS_ETCD_VALIDATION_FAILED))
		return err
	}

	if !isValid {
		metrics.EtcdFailure.WithLabelValues("register:ValidateServiceEndpoint", serviceName).Inc()
		log.Error().Dict("custom_attributes", logger.Attrs().Str("status_code", string(logger.GALACTUS_ETCD_VALIDATION_FAILED)).Str("error", "endpoint failed validation")).Msg(logger.Msg(logger.GALACTUS_ETCD_VALIDATION_FAILED))
		return errors.New("register: endpoint validation failed")
	}
	// Marshaling v3.1 endpoint
	outBytes, err := endpoint.MarshalVTStrict()
	if err != nil {
		metrics.EtcdFailure.WithLabelValues("register:MarshalVTStrict", serviceName).Inc()
		metrics.EtcdFailure.WithLabelValues("register", serviceName).Inc()
		return err
	}

	if isLRC {
		log.Info().Msgf("[v4] REGISTER (LRC→v4 catalog): %s", endpointKey)
	} else if !writeCatalog {
		log.Info().Msgf("REGISTER (v3.1 catalog write blocked, skipped %s): %s", catalogKey, endpointKey)
	} else {
		log.Info().Msgf("REGISTER: %s", endpointKey)
	}

	ops := registerOps(endpointKey, string(outBytes), catalogKey, writeCatalog, nodeKey, clusterKey)

	ctx, cancel := context.WithTimeout(a.ctx, 60*time.Second)
	defer cancel()
	res, err := a.Client.KV.Txn(ctx).Then(ops...).Commit()

	if err != nil || !res.Succeeded {
		if err == nil {
			err = fmt.Errorf("transaction failed to key = %s", endpointKey)
		} else {
			a.handleError(err)
		}
		metrics.EtcdFailure.WithLabelValues("register:Txn", serviceName).Inc()
		return err
	}

	metrics.EtcdSuccess.WithLabelValues("register:Txn", serviceName).Inc()

	// Flow-1 traceability (LOG-10): the endpoint-write hop succeeded. Emit at INFO
	// with pod_ip + key (etcd family — no pod_name in etcd scope).
	log.Info().Dict("custom_attributes", logger.Attrs().
		Str("status_code", string(logger.GALACTUS_ENDPOINT_WRITTEN)).
		Str("pod_ip", endpoint.Address.GetValue()).
		Str("key", endpointKey)).
		Msg(logger.Msg(logger.GALACTUS_ENDPOINT_WRITTEN))

	multiEntityEnabledForService, ok := a.MultiEntityServices.Load(serviceName)
	if ok {
		multiEntityEnabledForService = true
	} else {
		multiEntityEnabledForService = false
	}
	multiEntityEnabledInEtcd := a.MultiEntityEnabled.Load()
	if multiEntityEnabledInEtcd && multiEntityEnabledForService.(bool) {
		log.Info().Msgf("REGISTER[multi-entity]: %s", endpointKey)

		ctx, cancel := context.WithTimeout(a.ctx, 60*time.Second)
		defer cancel()
		res, err := a.SecondaryClient.KV.Txn(ctx).Then(ops...).Commit()

		if err != nil || !res.Succeeded {
			metrics.MultiEntitySecondaryWriteFailure.WithLabelValues("register", serviceName).Inc()
			if err != nil {
				log.Error().Dict("custom_attributes", logger.Attrs().
					Str("status_code", string(logger.GALACTUS_ETCD_SECONDARY_WRITE_FAILED)).
					Str("service", serviceName).
					Str("operation", "register").
					Str("error", err.Error())).
					Msg("secondary etcd write failed; primary registration succeeded")
			} else {
				log.Error().Dict("custom_attributes", logger.Attrs().
					Str("status_code", string(logger.GALACTUS_ETCD_SECONDARY_WRITE_FAILED)).
					Str("service", serviceName).
					Str("operation", "register")).
					Msg("secondary etcd transaction not committed; primary registration succeeded")
			}
			// Do NOT return -- primary write already succeeded
		} else {
			metrics.EtcdSuccess.WithLabelValues("register:MultiEntityTxn", serviceName).Inc()
		}
	}

	return nil
}

// CleanSecondaryService deletes this cluster's keys for a service from the
// SECONDARY etcd only. Used when multi-entity is disabled for a service (LRC
// entities annotation removed or shrunk to one entity): primary keys stay
// untouched, the secondary copies must be removed. The secondary etcd holds
// the same service prefix for every cluster registered into that family, plus
// any natively-owned same-named service, so deletion is scoped to endpoints
// whose Meta["cluster"] matches this cluster; endpoints whose cluster cannot
// be determined are left alone. Catalog keys are shared across clusters and
// are removed only when no other cluster's endpoints remain.
func (a *AdapterV2) CleanSecondaryService(serviceName string) error {
	if a.SecondaryClient == nil {
		return nil
	}
	if serviceName == "" || strings.Contains(serviceName, "/") {
		return fmt.Errorf("cleanSecondaryService: invalid service name %q", serviceName)
	}

	ctx, cancel := context.WithTimeout(a.ctx, 60*time.Second)
	defer cancel()

	clusterName := utils.GetClusterName()
	endpointKeyPrefix := fmt.Sprintf("%s/%s/", EndpointPrefix, serviceName)
	res, err := a.SecondaryClient.KV.Get(ctx, endpointKeyPrefix, clientv3.WithPrefix())
	if err != nil {
		metrics.MultiEntitySecondaryWriteFailure.WithLabelValues("cleanSecondaryService", serviceName).Inc()
		a.handleError(err)
		return err
	}
	var endpointKeys []string
	nodeKeys := make(map[string]bool)
	var foreign int
	for _, kv := range res.Kvs {
		ep := &servicev1.ServiceEndpoint{}
		if err := ep.UnmarshalVT(kv.Value); err != nil || ep.Meta["cluster"] != clusterName {
			foreign++
			continue
		}
		endpointKeys = append(endpointKeys, string(kv.Key))
		// endpoint key: /nexus/v3.1/endpoint/<svc>/<node>/<pod>/<zone>/<ip_port>
		parts := strings.Split(string(kv.Key), "/")
		if len(parts) < 7 {
			continue
		}
		nodeKeys[fmt.Sprintf("%s/%s/%s/%s", NodePrefix, parts[5], serviceName, parts[6])] = true
	}

	log.Info().Msgf("CLEAN[multi-entity secondary]: %s (%d endpoints this cluster, %d foreign kept, %d node keys)", serviceName, len(endpointKeys), foreign, len(nodeKeys))

	var multiErr error
	for _, key := range endpointKeys {
		if _, err := a.SecondaryClient.KV.Delete(ctx, key); err != nil {
			multiErr = errors.Join(multiErr, err)
		}
	}
	for nodeKey := range nodeKeys {
		if _, err := a.SecondaryClient.KV.Delete(ctx, nodeKey); err != nil {
			multiErr = errors.Join(multiErr, err)
		}
	}
	if foreign == 0 && multiErr == nil {
		for _, prefix := range []string{
			fmt.Sprintf("%s/%s/", CatalogPrefix, serviceName),
			fmt.Sprintf("%s/%s/", CatalogPrefixV4, serviceName),
		} {
			if _, err := a.SecondaryClient.KV.Delete(ctx, prefix, clientv3.WithPrefix()); err != nil {
				multiErr = errors.Join(multiErr, err)
			}
		}
	}
	if multiErr != nil {
		metrics.MultiEntitySecondaryWriteFailure.WithLabelValues("cleanSecondaryService", serviceName).Inc()
		log.Error().Dict("custom_attributes", logger.Attrs().
			Str("status_code", string(logger.GALACTUS_ETCD_SECONDARY_WRITE_FAILED)).
			Str("service", serviceName).
			Str("operation", "cleanSecondaryService").
			Str("error", multiErr.Error())).
			Msg("secondary etcd service cleanup failed")
		return multiErr
	}
	return nil
}

func (a *AdapterV2) handleError(err error) {
	switch {
	case errors.Is(err, context.Canceled):
		log.Error().Dict("custom_attributes", logger.Attrs().Str("status_code", string(logger.GALACTUS_ETCD_CONNECTION_ERROR)).Str("error", err.Error())).Msg(logger.Msg(logger.GALACTUS_ETCD_CONNECTION_ERROR))
	case errors.Is(err, context.DeadlineExceeded):
		log.Error().Dict("custom_attributes", logger.Attrs().Str("status_code", string(logger.GALACTUS_ETCD_CONNECTION_ERROR)).Str("error", err.Error())).Msg(logger.Msg(logger.GALACTUS_ETCD_CONNECTION_ERROR))
	case errors.Is(err, rpctypes.ErrEmptyKey):
		log.Error().Dict("custom_attributes", logger.Attrs().Str("status_code", string(logger.GALACTUS_ETCD_CONNECTION_ERROR)).Str("error", err.Error())).Msg(logger.Msg(logger.GALACTUS_ETCD_CONNECTION_ERROR))
	default:
		log.Error().Dict("custom_attributes", logger.Attrs().Str("status_code", string(logger.GALACTUS_ETCD_CONNECTION_ERROR)).Str("error", err.Error())).Msg(logger.Msg(logger.GALACTUS_ETCD_CONNECTION_ERROR))
	}
}

func GetZone(endpoint *servicev1.ServiceEndpoint) string {
	tagsMap := make(map[string]string)
	del := ":"
	for _, s := range endpoint.Tags {
		if !strings.Contains(s, del) {
			continue
		}
		split := strings.Split(s, del)
		tagsMap[split[0]] = split[1]
	}

	val, ok := tagsMap["injected_zone"]
	if ok && val != "" {
		return val
	}
	val, ok = tagsMap["zone"]
	if ok && val != "" {
		return val
	}
	return utils.EndpointFallbackZone
}

func (a *AdapterV2) RemoveNodeKeyEndpoint(endpoint *servicev1.ServiceEndpoint) error {
