	nodeName, podName := parts[0], parts[1]
	nodeKey := fmt.Sprintf("%s/%s/%s/%s", NodePrefix, nodeName, endpoint.Service.GetValue(), podName)

	if !validator.ValidateKeyPath(nodeKey) {
		metrics.EtcdFailure.WithLabelValues("removeNodeKeyEndpoint:ValidateKeyPath", "").Inc()
		log.Warn().Msgf("RemoveNodeKeyEndpoint: validation failed for nodeKey=%s", nodeKey)
		return errors.New("removeNodeKeyEndpoint: validation failed for nodeKey")
	}

	ctx, cancel := context.WithTimeout(a.ctx, 60*time.Second)
	defer cancel()
	// deleting v3.1 nodeKey
	log.Debug().Msgf("[RemoveNodeKeyEndpoint] Deleting NodeKey: %v", nodeKey)
	_, err := a.Client.KV.Delete(ctx, nodeKey)
	if err != nil {
		metrics.EtcdFailure.WithLabelValues("removeNodeKeyEndpoint:Delete", "").Inc()
		a.handleError(err)
		return err
	}

	multiEntityEnabledForService, ok := a.MultiEntityServices.Load(endpoint.Service.GetValue())
	if ok {
		multiEntityEnabledForService = true
	} else {
		multiEntityEnabledForService = false
	}
	multiEntityEnabledInEtcd := a.MultiEntityEnabled.Load()
	if multiEntityEnabledInEtcd && multiEntityEnabledForService.(bool) {
		ctx, cancel := context.WithTimeout(a.ctx, 60*time.Second)
		defer cancel()
		// deleting v3.1 nodeKey
		_, err := a.SecondaryClient.KV.Delete(ctx, nodeKey)
		if err != nil {
			metrics.MultiEntitySecondaryWriteFailure.WithLabelValues("removeNodeKeyEndpoint", endpoint.Service.GetValue()).Inc()
